"""Retry policy for outbound HTTP calls made through shipclient."""

import re
from datetime import datetime, timezone

# Defaults from the HTTP client standard (v3) and rate limit handling.
DEFAULT_ATTEMPTS = 5
DEFAULT_CAP = 8.0
DEFAULT_MAX_RETRY_AFTER = 30.0
FIRST_DELAY = 0.25

RETRYABLE_STATUSES = {429, 502, 503, 504}
IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
NON_IDEMPOTENT_METHODS = {"POST", "PATCH"}

# Current retry profiles, keyed by lower-case service name:
# (attempts in total, backoff cap, longest accepted Retry-After wait)
RETRY_PROFILES = {
    "catalog": (6, 8, 30),
    "ledger": (8, 3, 60),
    "auth": (6, 6, 20),
    "payments": (3, 1, 30),
    "ledger-export": (4, 8, 10),
    "reports": (9, 5, 120),
    "inventory": (7, 4, 90),
    "search": (10, 12, 45),
    "shipping": (8, 3, 40),
    "media": (5, 8, 15),
}

_MONTHS = {
    m: i + 1
    for i, m in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun",
         "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]
    )
}
_DAYS = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}
_HTTP_DATE = re.compile(
    r"([A-Z][a-z]{2}), (\d{2}) ([A-Z][a-z]{2}) (\d{4}) (\d{2}):(\d{2}):(\d{2}) GMT",
    re.ASCII,
)
_INTEGER = re.compile(r"[0-9]+", re.ASCII)


def _header(headers: dict[str, str] | None, name: str) -> str | None:
    name = name.lower()
    for key, value in (headers or {}).items():
        if isinstance(key, str) and key.lower() == name:
            return value
    return None


def _retry_after_seconds(value: str | None, now: datetime) -> float | None:
    """Parsed Retry-After wait in seconds, or None if absent or malformed."""
    if value is None:
        return None
    value = value.strip()
    if _INTEGER.fullmatch(value):
        return float(int(value))
    m = _HTTP_DATE.fullmatch(value)
    if not m:
        return None
    day_name, dd, mon, yyyy, hh, mm, ss = m.groups()
    if day_name not in _DAYS or mon not in _MONTHS:
        return None
    try:
        when = datetime(
            int(yyyy), _MONTHS[mon], int(dd), int(hh), int(mm), int(ss),
            tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (when - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    # Retry profile for the service, if one is currently in force.
    attempts, cap, max_retry_after = (
        DEFAULT_ATTEMPTS, DEFAULT_CAP, DEFAULT_MAX_RETRY_AFTER,
    )
    service = _header(request_headers, "X-Service")
    if service is not None and service.lower() in RETRY_PROFILES:
        attempts, cap, max_retry_after = RETRY_PROFILES[service.lower()]

    # Which failures are retried.
    if status is not None and status not in RETRYABLE_STATUSES:
        return None

    # Which requests are retried.
    verb = (method or "").upper()
    if verb in IDEMPOTENT_METHODS:
        pass
    elif verb in NON_IDEMPOTENT_METHODS:
        key = _header(request_headers, "Idempotency-Key")
        if key is None or not key.strip():
            return None
    else:
        return None

    # How many attempts.
    if attempt >= attempts:
        return None

    # Exponential backoff.
    delay = FIRST_DELAY
    for _ in range(max(attempt, 1) - 1):
        delay *= 2
        if delay >= cap:
            break
    delay = min(delay, float(cap))

    # Retry-After applies to 429 and 503 only.
    if status in (429, 503):
        wait = _retry_after_seconds(_header(response_headers, "Retry-After"), now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(delay, wait)

    return float(delay)
